//! Bounded per-upload state. Worker I/O is always performed outside the state lock.
use std::{collections::HashMap,sync::{Arc,Mutex,atomic::{AtomicBool,Ordering}},time::{Duration,Instant}};
#[derive(Clone,Debug)] pub struct Owner {pub agent:String,pub workspace:String,pub session:String,pub worker_stream:String,pub transactional:bool,pub request_id:String,pub signature:String}
const STAGING_PAYLOAD_QUOTA:u64=10*1024*1024*1024;
const STAGING_DISK_QUOTA:u64=STAGING_PAYLOAD_QUOTA+(STAGING_PAYLOAD_QUOTA/1024)*20;
fn reservation(expected:u64)->Option<u64>{let chunks=expected.checked_add(1023)?/1024;expected.checked_add(chunks.checked_mul(20)?)}
struct Entry {owner:Owner,expected:u64,reserved:u64,offset:u64,touched:Instant,in_flight:bool,finishing:bool,cancelled:Arc<AtomicBool>,cleanup_queued:bool,cleanup_done:bool}
#[derive(Clone)] pub struct Ticket {pub owner:Owner,cancelled:Arc<AtomicBool>,size:u64}
impl Ticket {pub fn cancelled(&self)->bool{self.cancelled.load(Ordering::Acquire)}}
#[derive(Debug)] pub enum CompletionError {Unavailable,CancelWorker(Owner)}
pub struct Uploads {state:Mutex<HashMap<String,Entry>>,limit:usize,idle:Duration}
impl Uploads {
 pub fn new(limit:usize,idle:Duration)->Self{Self{state:Mutex::new(HashMap::new()),limit:limit.max(1),idle}}
 pub fn active_count(&self,now:Instant)->Result<usize,&'static str>{let s=self.state.lock().map_err(|_|"unavailable")?;Ok(s.values().filter(|e|!e.cancelled.load(Ordering::Acquire)&&(e.finishing||now.saturating_duration_since(e.touched)<self.idle)).count())}
 pub fn begin(&self,id:String,owner:Owner,expected:u64,now:Instant)->Result<(),&'static str>{let mut s=self.state.lock().map_err(|_|"unavailable")?;if id.is_empty()||s.len()>=self.limit||s.contains_key(&id)||s.values().any(|e|e.owner.agent==owner.agent){return Err("busy")}let reserved=reservation(expected).ok_or("quota exceeded")?;let used=s.values().try_fold(0u64,|sum,e|sum.checked_add(e.reserved)).ok_or("quota exceeded")?;let payload=s.values().try_fold(0u64,|sum,e|sum.checked_add(e.expected)).ok_or("quota exceeded")?;if payload.checked_add(expected).is_none_or(|v|v>STAGING_PAYLOAD_QUOTA)||used.checked_add(reserved).is_none_or(|v|v>STAGING_DISK_QUOTA){return Err("quota exceeded")}s.insert(id,Entry{owner,expected,reserved,offset:0,touched:now,in_flight:false,finishing:false,cancelled:Arc::new(AtomicBool::new(false)),cleanup_queued:false,cleanup_done:false});Ok(())}
 pub fn find_request(&self,agent:&str,workspace:&str,session:&str,request_id:&str,signature:&str)->Result<Option<(String,bool,u64)>,&'static str>{
  let s=self.state.lock().map_err(|_|"unavailable")?;for (id,e) in s.iter(){if e.owner.agent==agent&&e.owner.workspace==workspace&&e.owner.session==session&&e.owner.request_id==request_id{if e.owner.signature!=signature||e.cancelled.load(Ordering::Acquire){return Err("request conflict")}return Ok(Some((id.clone(),!e.owner.worker_stream.is_empty(),e.offset)))}}Ok(None)
 }
 pub fn cancel_request(&self,agent:&str,workspace:&str,session:&str,request_id:&str)->Option<Owner>{let mut s=self.state.lock().ok()?;let e=s.values_mut().find(|e|e.owner.agent==agent&&e.owner.workspace==workspace&&e.owner.session==session&&e.owner.request_id==request_id)?;Self::mark(e)}
 pub fn reserve(&self,id:&str,agent:&str,workspace:&str,session:&str,offset:u64,size:u64,now:Instant)->Result<Ticket,&'static str>{let mut s=self.state.lock().map_err(|_|"unavailable")?;let e=s.get_mut(id).ok_or("unavailable")?;if e.owner.agent!=agent||e.owner.workspace!=workspace||e.owner.session!=session||e.cancelled.load(Ordering::Acquire){return Err("unavailable")}if now.saturating_duration_since(e.touched)>=self.idle{return Err("expired")}if e.in_flight||size==0||size>65536||offset!=e.offset||(size<1024&&size!=e.expected.saturating_sub(offset))||offset.checked_add(size).is_none_or(|n|n>e.expected){return Err("invalid chunk")}e.in_flight=true;Ok(Ticket{owner:e.owner.clone(),cancelled:e.cancelled.clone(),size})}
 pub fn reserve_finish(&self,id:&str,agent:&str,workspace:&str,session:&str,now:Instant)->Result<Ticket,&'static str>{let mut s=self.state.lock().map_err(|_|"unavailable")?;let e=s.get_mut(id).ok_or("unavailable")?;if e.owner.agent!=agent||e.owner.workspace!=workspace||e.owner.session!=session||e.cancelled.load(Ordering::Acquire){return Err("unavailable")}if now.saturating_duration_since(e.touched)>=self.idle{return Err("expired")}if e.in_flight||e.offset!=e.expected{return Err("incomplete upload")}e.in_flight=true;e.finishing=true;Ok(Ticket{owner:e.owner.clone(),cancelled:e.cancelled.clone(),size:0})}
 pub fn finish(&self,id:&str,t:&Ticket)->Result<Owner,&'static str>{let mut s=self.state.lock().map_err(|_|"unavailable")?;let e=s.get_mut(id).ok_or("unavailable")?;if !Arc::ptr_eq(&e.cancelled,&t.cancelled)||!e.in_flight||t.size!=0{return Err("unavailable")}if t.cancelled(){e.in_flight=false;if e.cleanup_done{s.remove(id);}return Err("cancelled")}Ok(s.remove(id).ok_or("unavailable")?.owner)}
 pub fn complete(&self,id:&str,t:&Ticket,size:u64,ok:bool,now:Instant)->Result<u64,CompletionError>{let mut s=self.state.lock().map_err(|_|CompletionError::Unavailable)?;let e=s.get_mut(id).ok_or(CompletionError::Unavailable)?;if !Arc::ptr_eq(&e.cancelled,&t.cancelled)||!e.in_flight||size!=t.size{return Err(CompletionError::Unavailable)}if !ok||t.cancelled(){e.cancelled.store(true,Ordering::Release);e.in_flight=false;if e.cleanup_done{s.remove(id);return Err(CompletionError::Unavailable)}if !e.cleanup_queued{e.cleanup_queued=true;return Err(CompletionError::CancelWorker(e.owner.clone()))}return Err(CompletionError::Unavailable)}e.offset=e.offset.checked_add(size).ok_or(CompletionError::Unavailable)?;e.in_flight=false;e.touched=now;Ok(e.offset)}
 fn mark(e:&mut Entry)->Option<Owner>{e.cancelled.store(true,Ordering::Release);if e.cleanup_queued||e.owner.worker_stream.is_empty(){return None}e.cleanup_queued=true;Some(e.owner.clone())}
 pub fn set_stream(&self,id:&str,stream:String)->Result<Option<Owner>,&'static str>{let mut s=self.state.lock().map_err(|_|"unavailable")?;let e=s.get_mut(id).ok_or("unavailable")?;if stream.is_empty()||!e.owner.worker_stream.is_empty(){return Err("invalid stream")}e.owner.worker_stream=stream;if e.cancelled.load(Ordering::Acquire){e.cleanup_queued=true;Ok(Some(e.owner.clone()))}else{Ok(None)}}
 pub fn abandon_pending(&self,id:&str){if let Ok(mut s)=self.state.lock(){if s.get(id).is_some_and(|e|e.owner.worker_stream.is_empty()){s.remove(id);}}}
 pub fn cancel_one(&self,id:&str,agent:&str,workspace:&str,session:&str)->Option<Owner>{let mut s=self.state.lock().ok()?;let e=s.get_mut(id)?;if e.owner.agent!=agent||e.owner.workspace!=workspace||e.owner.session!=session{return None}Self::mark(e)}
 pub fn cancel_matching(&self,agent:Option<&str>,workspace:Option<&str>,now:Instant)->Vec<Owner>{let Ok(mut s)=self.state.lock()else{return vec![]};s.values_mut().filter(|e|agent.is_some_and(|x|x==e.owner.agent)||workspace.is_some_and(|x|x==e.owner.workspace)||e.cancelled.load(Ordering::Acquire)||(!e.finishing&&now.saturating_duration_since(e.touched)>=self.idle)).filter_map(Self::mark).collect()}
 /// Only call after the worker has confirmed cancellation or its session is gone.
 pub fn cleanup_complete(&self,o:&Owner){if let Ok(mut s)=self.state.lock(){s.retain(|_,e|{if !(e.cleanup_queued&&e.owner.workspace==o.workspace&&e.owner.session==o.session&&e.owner.worker_stream==o.worker_stream){return true}if e.in_flight{e.cleanup_done=true;true}else{false}});}}
 pub fn retry_cleanup(&self,o:&Owner){if let Ok(mut s)=self.state.lock(){if let Some(e)=s.values_mut().find(|e|e.owner.workspace==o.workspace&&e.owner.session==o.session&&e.owner.worker_stream==o.worker_stream){e.cleanup_queued=false;}}}
}
#[cfg(test)] mod tests{use super::*;#[test]fn active_count_excludes_cancelled_and_expired(){let now=Instant::now();let s=Uploads::new(3,Duration::from_secs(5));s.begin("a".into(),owner(),1,now).unwrap();assert_eq!(s.active_count(now).unwrap(),1);assert_eq!(s.active_count(now+Duration::from_secs(6)).unwrap(),0);s.cancel_one("a","a","w","s");assert_eq!(s.active_count(now).unwrap(),0);}fn owner()->Owner{Owner{agent:"a".into(),workspace:"w".into(),session:"s".into(),worker_stream:"q".into(),transactional:false,request_id:String::new(),signature:String::new()}}#[test]fn cancellation_keeps_slot_until_confirmed(){let now=Instant::now();let s=Uploads::new(1,Duration::from_secs(5));s.begin("x".into(),owner(),1,now).unwrap();let t=s.reserve("x","a","w","s",0,1,now).unwrap();let pending=s.cancel_matching(Some("a"),None,now);assert_eq!(pending.len(),1);assert!(t.cancelled());assert!(s.complete("x",&t,1,true,now).is_err());assert!(s.begin("y".into(),owner(),1,now).is_err());s.cleanup_complete(&pending[0]);assert!(s.begin("y".into(),owner(),1,now).is_ok());}#[test]fn failures_require_worker_cleanup(){let now=Instant::now();let s=Uploads::new(1,Duration::from_secs(5));s.begin("x".into(),owner(),2,now).unwrap();let t=s.reserve("x","a","w","s",0,2,now).unwrap();let o=match s.complete("x",&t,2,false,now){Err(CompletionError::CancelWorker(o))=>o,_=>panic!()};assert!(s.begin("y".into(),owner(),1,now).is_err());s.cleanup_complete(&o);assert!(s.begin("y".into(),owner(),1,now).is_ok());}#[test]fn cancel_during_begin_queues_worker_after_it_starts(){let now=Instant::now();let s=Uploads::new(1,Duration::from_secs(5));let mut o=owner();o.worker_stream.clear();s.begin("x".into(),o,1,now).unwrap();assert!(s.cancel_matching(Some("a"),None,now).is_empty());let pending=s.set_stream("x","q".into()).unwrap().unwrap();assert_eq!(pending.worker_stream,"q");assert!(s.begin("y".into(),owner(),1,now).is_err());s.cleanup_complete(&pending);assert!(s.begin("y".into(),owner(),1,now).is_ok());}
#[test]fn cleanup_waits_for_running_operation(){let now=Instant::now();let s=Uploads::new(1,Duration::from_secs(5));s.begin("x".into(),owner(),1,now).unwrap();let t=s.reserve("x","a","w","s",0,1,now).unwrap();let c=s.cancel_matching(Some("a"),None,now);s.cleanup_complete(&c[0]);assert!(s.begin("y".into(),owner(),1,now).is_err());assert!(s.complete("x",&t,1,true,now).is_err());assert!(s.begin("y".into(),owner(),1,now).is_ok());}
#[test]fn failed_queue_delivery_is_retried(){let now=Instant::now();let s=Uploads::new(1,Duration::from_secs(5));s.begin("x".into(),owner(),1,now).unwrap();let c=s.cancel_matching(Some("a"),None,now);s.retry_cleanup(&c[0]);assert_eq!(s.cancel_matching(None,None,now).len(),1);}
#[test]fn failed_finish_releases_after_cleanup_in_both_orders(){for cleanup_first in [false,true]{let now=Instant::now();let s=Uploads::new(1,Duration::from_secs(5));s.begin("x".into(),owner(),0,now).unwrap();let t=s.reserve_finish("x","a","w","s",now).unwrap();let o=s.cancel_one("x","a","w","s").unwrap();if cleanup_first{s.cleanup_complete(&o);}assert!(s.complete("x",&t,0,false,now).is_err());if !cleanup_first{s.cleanup_complete(&o);}assert!(s.begin("y".into(),owner(),1,now).is_ok(),"cleanup_first={cleanup_first}");}}
#[test]fn quota_is_reserved_until_worker_cleanup(){let now=Instant::now();let s=Uploads::new(4,Duration::from_secs(5));let first=owner();let mut second=owner();second.agent="b".into();let mut third=owner();third.agent="c".into();let gib=1024*1024*1024;s.begin("a".into(),first.clone(),4*gib,now).unwrap();s.begin("b".into(),second,4*gib,now).unwrap();assert_eq!(s.begin("c".into(),third.clone(),3*gib,now),Err("quota exceeded"));let cancelled=s.cancel_matching(Some("a"),None,now);assert_eq!(cancelled.len(),1);assert_eq!(s.begin("c".into(),third.clone(),3*gib,now),Err("quota exceeded"));s.cleanup_complete(&cancelled[0]);assert!(s.begin("c".into(),third,3*gib,now).is_ok());}
#[test]fn concurrent_quota_reservations_are_atomic(){let now=Instant::now();let s=Arc::new(Uploads::new(4,Duration::from_secs(5)));let barrier=Arc::new(std::sync::Barrier::new(3));let mut threads=Vec::new();for n in 0..2{let s=s.clone();let b=barrier.clone();threads.push(std::thread::spawn(move||{let mut o=owner();o.agent=format!("agent-{n}");b.wait();s.begin(format!("upload-{n}"),o,6*1024*1024*1024,now)}));}barrier.wait();let results=threads.into_iter().map(|t|t.join().unwrap()).collect::<Vec<_>>();assert_eq!(results.iter().filter(|r|r.is_ok()).count(),1);assert_eq!(results.iter().filter(|r|matches!(r,Err("quota exceeded"))).count(),1);}
#[test]fn exact_ten_gib_is_allowed_and_reserves_overhead(){let now=Instant::now();let s=Uploads::new(2,Duration::from_secs(5));s.begin("a".into(),owner(),10*1024*1024*1024,now).unwrap();let mut b=owner();b.agent="b".into();assert_eq!(s.begin("b".into(),b.clone(),1,now),Err("quota exceeded"));let pending=s.cancel_matching(Some("a"),None,now);s.cleanup_complete(&pending[0]);assert!(s.begin("b".into(),b,1,now).is_ok());}
#[test]fn tiny_nonfinal_chunks_cannot_bypass_staging_quota(){let now=Instant::now();let s=Uploads::new(1,Duration::from_secs(5));s.begin("x".into(),owner(),2048,now).unwrap();assert!(s.reserve("x","a","w","s",0,1,now).is_err());let t=s.reserve("x","a","w","s",0,1024,now).unwrap();assert!(s.complete("x",&t,1024,true,now).is_ok());let t=s.reserve("x","a","w","s",1024,1024,now).unwrap();assert!(s.complete("x",&t,1024,true,now).is_ok());}
#[test]fn active_finish_does_not_expire(){let now=Instant::now();let s=Uploads::new(1,Duration::from_secs(5));s.begin("x".into(),owner(),0,now).unwrap();let t=s.reserve_finish("x","a","w","s",now).unwrap();assert!(s.cancel_matching(None,None,now+Duration::from_secs(6)).is_empty());assert!(s.finish("x",&t).is_ok());}
#[test]fn finish_and_expiry(){let now=Instant::now();let s=Uploads::new(2,Duration::from_secs(5));s.begin("x".into(),owner(),2,now).unwrap();assert!(s.reserve_finish("x","a","w","s",now).is_err());let t=s.reserve("x","a","w","s",0,2,now).unwrap();assert!(matches!(s.complete("x",&t,2,true,now),Ok(2)));let f=s.reserve_finish("x","a","w","s",now).unwrap();assert!(s.finish("x",&f).is_ok());s.begin("z".into(),owner(),1,now).unwrap();assert_eq!(s.cancel_matching(None,None,now+Duration::from_secs(5)).len(),1);}}
